import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';

function PatientProfile() {
  const [profile, setProfile] = useState({
    birthDate: '',
    gender: '',
    bloodType: '',
    allergies: [],
    medicalHistory: '',
    emergencyContact: {
      name: '',
      relationship: '',
      phone: ''
    }
  });
  const [isEditing, setIsEditing] = useState(false);
  const [loading, setLoading] = useState(true);
  const navigate = useNavigate();

  // 获取用户信息
  const userEmail = localStorage.getItem('userEmail');
  const userRole = localStorage.getItem('userRole');

  useEffect(() => {
    // 检查用户权限
    if (!userEmail || userRole !== 'client') {
      navigate('/login');
      return;
    }

    // 在这里加载患者资料数据
    // 注意：API尚未实现，所以这里只是设置loading为false
    setLoading(false);
  }, [userEmail, userRole, navigate]);

  const handleInputChange = (e) => {
    const { name, value } = e.target;
    if (name.includes('.')) {
      const [parent, child] = name.split('.');
      setProfile({
        ...profile,
        [parent]: {
          ...profile[parent],
          [child]: value
        }
      });
    } else {
      setProfile({
        ...profile,
        [name]: value
      });
    }
  };

  const handleSubmit = (e) => {
    e.preventDefault();
    // 在这里提交患者资料
    // 注意：API尚未实现
    alert('资料保存功能尚未实现');
    setIsEditing(false);
  };

  if (loading) {
    return <div className="text-center mt-5">加载中...</div>;
  }

  return (
    <>
      <div className="login-background"></div>
      <div className="container mt-5">
        <div className="card">
          <div className="card-header bg-primary text-white">
            <h3>我的医疗档案</h3>
          </div>
          <div className="card-body">
            {isEditing ? (
              <form onSubmit={handleSubmit}>
                <div className="row">
                  <div className="col-md-6 mb-3">
                    <label className="form-label">出生日期</label>
                    <input
                      type="date"
                      className="form-control"
                      name="birthDate"
                      value={profile.birthDate}
                      onChange={handleInputChange}
                    />
                  </div>
                  <div className="col-md-6 mb-3">
                    <label className="form-label">性别</label>
                    <select
                      className="form-select"
                      name="gender"
                      value={profile.gender}
                      onChange={handleInputChange}
                    >
                      <option value="">-- 请选择 --</option>
                      <option value="male">男</option>
                      <option value="female">女</option>
                      <option value="other">其他</option>
                    </select>
                  </div>
                </div>

                <div className="mb-3">
                  <label className="form-label">血型</label>
                  <select
                    className="form-select"
                    name="bloodType"
                    value={profile.bloodType}
                    onChange={handleInputChange}
                  >
                    <option value="">-- 请选择 --</option>
                    <option value="A+">A+</option>
                    <option value="A-">A-</option>
                    <option value="B+">B+</option>
                    <option value="B-">B-</option>
                    <option value="AB+">AB+</option>
                    <option value="AB-">AB-</option>
                    <option value="O+">O+</option>
                    <option value="O-">O-</option>
                  </select>
                </div>

                <div className="mb-3">
                  <label className="form-label">过敏史</label>
                  <input
                    type="text"
                    className="form-control"
                    placeholder="用逗号分隔多项"
                    value={profile.allergies.join(', ')}
                    onChange={(e) => setProfile({...profile, allergies: e.target.value.split(',').map(item => item.trim())})}
                  />
                </div>

                <div className="mb-3">
                  <label className="form-label">病史</label>
                  <textarea
                    className="form-control"
                    name="medicalHistory"
                    rows="3"
                    value={profile.medicalHistory}
                    onChange={handleInputChange}
                  ></textarea>
                </div>

                <h5 className="mt-4">紧急联系人</h5>
                <div className="row">
                  <div className="col-md-4 mb-3">
                    <label className="form-label">姓名</label>
                    <input
                      type="text"
                      className="form-control"
                      name="emergencyContact.name"
                      value={profile.emergencyContact.name}
                      onChange={handleInputChange}
                    />
                  </div>
                  <div className="col-md-4 mb-3">
                    <label className="form-label">关系</label>
                    <input
                      type="text"
                      className="form-control"
                      name="emergencyContact.relationship"
                      value={profile.emergencyContact.relationship}
                      onChange={handleInputChange}
                    />
                  </div>
                  <div className="col-md-4 mb-3">
                    <label className="form-label">电话</label>
                    <input
                      type="text"
                      className="form-control"
                      name="emergencyContact.phone"
                      value={profile.emergencyContact.phone}
                      onChange={handleInputChange}
                    />
                  </div>
                </div>

                <div className="mt-3">
                  <button type="submit" className="btn btn-primary me-2">保存</button>
                  <button type="button" className="btn btn-secondary" onClick={() => setIsEditing(false)}>取消</button>
                </div>
              </form>
            ) : (
              <div>
                <p className="text-center">当前尚未填写个人医疗档案信息。</p>
                <div className="text-center">
                  <button className="btn btn-primary" onClick={() => setIsEditing(true)}>编辑资料</button>
                </div>
              </div>
            )}
          </div>
        </div>
      </div>
    </>
  );
}

export default PatientProfile;
